const toggle=document.querySelector(".menu-toggle"),sidebar=document.querySelector(".sidebar"),links=document.querySelectorAll(".nav-link");toggle?.addEventListener("click",()=>{const e=sidebar.classList.toggle("open");toggle.setAttribute("aria-expanded",e)}),links.forEach(e=>{e.addEventListener("click",()=>{sidebar.classList.remove("open"),toggle?.setAttribute("aria-expanded","false")})});const sections=document.querySelectorAll("main section[id]"),observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),links.forEach(t=>t.classList.toggle("active",t.getAttribute("href")===`#${e.target.id}`)))})},{rootMargin:"-35% 0px -55% 0px"});sections.forEach(e=>observer.observe(e)),window.addEventListener("pointermove",e=>{document.documentElement.style.setProperty("--mouse-x",`${e.clientX}px`),document.documentElement.style.setProperty("--mouse-y",`${e.clientY}px`)});const contactForm=document.querySelector("#contact-form"),formStatus=document.querySelector("#form-status");contactForm?.addEventListener("submit",async e=>{e.preventDefault(),formStatus.textContent="Sending securely through the Go service...";const t=await fetch("/api/contact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(new FormData(contactForm)))}),n=await t.json();formStatus.textContent=n.message,t.ok&&contactForm.reset()})